			table_col_minority: 'Mapa ng minorya',
			table_col_direction: 'Direksyon / Benepisyaryo',
			table_r1_a: 'Sumusunod ang hangganan sa umiiral na mga linya ng munisipyo (70–85% pamantayang Canadian)',
			table_r1_b: '80% — sa loob ng pamantayan',
